<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'

type RecordRow = { id: number; tanggal: string; status: string; alasan: string; jenis_materi: string; jilid: string; nama_surat: string; halaman: string; hasil_talaqqi: string; on_holiday?: boolean }
type Cell = { session_date: string; state: string; complete: boolean; missing_fields: string[]; records: RecordRow[]; record: RecordRow | null; owner: { nama_halaqoh: string; nama_ustadz: string }; expected: boolean; in_schedule: boolean; verified_roster: boolean; roster_source: string; fingerprint: string }
type Row = { id: number; nama_bapak: string; anak: string; kategori: string; status_aktif: boolean; nama_halaqoh: string; nama_ustadz: string; hadir: number; sakit: number; izin: number; alpha: number; expected: number; complete_input: number; missing_presensi: number; missing_capaian: number; missing_keterangan: number; conflicts: number; unverified: number; hadir_percent: number | null; coverage_percent: number | null; provisional: boolean; quality: string; quality_label: string; risk_label: string; terakhir_hadir: string; materi_terakhir: string; details: Cell[] }
type Group = { id: number; nama: string; nama_ustadz: string; total_anggota: number; hadir: number; sakit: number; izin: number; alpha: number; hadir_percent: number | null; coverage_percent: number | null; provisional: boolean }
type Summary = { peserta: number; peserta_periode: number; peserta_sesi: number; total_halaqoh: number; rawan: number; hadir: number; sakit: number; izin: number; alpha: number; expected: number; complete_input: number; missing_presensi: number; missing_capaian: number; missing_keterangan: number; conflicts: number; unverified: number; hadir_percent: number | null; coverage_percent: number | null; provisional: boolean }
type Report = { rows: Row[]; summary: Summary; halaqoh: Group[]; guru: Group[]; trend: Array<{ tanggal: string; hadir: number; sakit: number; izin: number; alpha: number; expected: number; complete_input: number; peserta_roster: number | null; roster_verified: boolean; provisional: boolean }>; schema_ready: boolean; tracked_from: string; filters: Record<string, string> }
type Envelope = { status: string; data: Report; meta: { page: number; limit: number; total: number; pages: number }; message?: string }
const props = defineProps<{ role: string; mode: 'progress' | 'rekap'; csrf: string }>()
const emit = defineEmits<{ unauthorized: [] }>()
const filters = reactive({ start_date: monthStart(), end_date: today(), halaqoh_id: '', ustadz_id: '', kategori: '', aktif: '', kelas: '', search: '', kelengkapan: '', risk: '' })
const report = ref<Report | null>(null)
const page = ref(1)
const pages = ref(1)
const total = ref(0)
const loading = ref(false)
const saving = ref('')
const error = ref('')
const notice = ref('')
const verifyChoice = reactive<Record<string, string>>({})
const verifyNote = reactive<Record<string, string>>({})
const statusNames: Record<string, string> = { H: 'Hadir', S: 'Sakit', I: 'Izin', A: 'Alfa' }
const stateNames: Record<string, string> = { complete: 'Lengkap', missing: 'Belum diinput', baseline: 'Capaian awal; bukan presensi', conflict: 'Perlu verifikasi', invalid_date: 'Tanggal pada hari libur', capaian: 'Capaian belum lengkap', presensi_incomplete: 'Keterangan belum lengkap' }

async function load(target = page.value) {
  loading.value = true; error.value = ''; notice.value = ''
  try {
    const query = new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== '')))
    query.set('page', String(target)); query.set('limit', '50')
    const response = await fetch(`/api/v1/reports/tahsin?${query}`, { credentials: 'same-origin', cache: 'no-store', headers: { Accept: 'application/json' } })
    const body = await response.json() as Envelope
    if (response.status === 401) { emit('unauthorized'); throw new Error('Sesi login berakhir. Masuk kembali.') }
    if (!response.ok || body.status !== 'ok') throw new Error(body.message || 'Rekap canonical Tahsin belum dapat dimuat.')
    report.value = body.data; page.value = body.meta.page; pages.value = body.meta.pages; total.value = body.meta.total
  } catch (e) { error.value = e instanceof Error ? e.message : 'Rekap canonical Tahsin belum dapat dimuat.' }
  finally { loading.value = false }
}
function applyFilters() { page.value = 1; void load(1) }
function move(delta: number) { const next = Math.max(1, Math.min(pages.value, page.value + delta)); void load(next) }
function cellKey(row: Row, cell: Cell) { return `${row.id}:${cell.session_date}` }
function statusText(record: RecordRow | null) {
  if (!record) return 'Belum diinput; belum dinilai Alfa'
  if (record.status === 'H') return [record.jenis_materi === 'Iqro' ? `Iqro jilid ${record.jilid}` : record.nama_surat ? `Al-Qur’an ${record.nama_surat}` : 'Al-Qur’an', record.halaman ? `halaman/ayat ${record.halaman}` : '', record.hasil_talaqqi].filter(Boolean).join(' · ')
  return [statusNames[record.status] || record.status, record.alasan].filter(Boolean).join(' · ')
}
function percentage(value: number | null) { return value === null ? '—' : `${new Intl.NumberFormat('id-ID', { maximumFractionDigits: 1 }).format(value)}%` }
async function verify(row: Row, cell: Cell) {
  const key = cellKey(row, cell)
  if (verifyChoice[key] === undefined || verifyChoice[key] === '') { error.value = 'Pilih catatan yang telah diperiksa atau nyatakan hanya sebagai capaian awal.'; return }
  const choice = Number(verifyChoice[key])
  saving.value = key; error.value = ''; notice.value = ''
  try {
    const response = await fetch('/api/v1/reports/tahsin/verifications', { method: 'POST', credentials: 'same-origin', cache: 'no-store', headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'X-CSRF-Token': props.csrf }, body: JSON.stringify({ wali_id: row.id, session: cell.session_date, fingerprint: cell.fingerprint, selected_id: choice, note: verifyNote[key] || '' }) })
    const body = await response.json() as { status: string; message?: string }
    if (response.status === 401) { emit('unauthorized'); throw new Error('Sesi login berakhir. Masuk kembali.') }
    if (!response.ok || body.status !== 'ok') throw new Error(body.message || 'Verifikasi belum dapat disimpan.')
    notice.value = `Verifikasi ${row.nama_bapak} untuk sesi ${cell.session_date} tersimpan; catatan sumber tetap utuh.`
    await load(page.value)
  } catch (e) { error.value = e instanceof Error ? e.message : 'Verifikasi belum dapat disimpan.' }
  finally { saving.value = '' }
}
function printReport() { window.print() }
function exportHref() {
  const query = new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== '')))
  return `/api/v1/reports/tahsin/export?${query}`
}
function raporHref(row: Row) {
  const query = new URLSearchParams({ wali_santri_id: String(row.id), start_date: filters.start_date, end_date: filters.end_date })
  return `/rapor?${query}`
}
function today() { return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()) }
function monthStart() { return `${today().slice(0, 7)}-01` }
onMounted(() => { void load(1) })
</script>

<template>
  <section class="tahsin-report-page">
    <header class="tr-heading"><div><span class="tr-kicker">LAPORAN CANONICAL · TAHSIN BAPAK & IBU</span><h1>{{ mode === 'progress' ? 'Progress wali santri' : 'Rekap Tahsin lengkap' }}</h1><p>Hanya catatan yang tersimpan dihitung sebagai presensi. Kewajiban sesi memakai histori roster; data kosong tidak dianggap Alfa.</p></div><div class="tr-export-actions no-print"><a class="tr-print" :class="{ disabled: !report }" :href="report ? exportHref() : undefined" :aria-disabled="!report">Unduh Excel</a><button class="tr-print" :disabled="!report" @click="printReport">Cetak / Simpan PDF</button></div></header>
    <p v-if="error" class="tr-error" role="alert">{{ error }} <button @click="load(page)">Coba lagi</button></p><p v-if="notice" class="tr-notice" role="status">{{ notice }}</p>
    <p v-if="report && !report.schema_ready" class="tr-warning" role="status">Histori roster belum aktif. Catatan yang tersimpan tetap tampil; kewajiban dan kekosongan roster sesi lama tidak ditebak.</p>
    <form class="tr-filters no-print" @submit.prevent="applyFilters"><label>Awal sesi<input v-model="filters.start_date" type="date" required></label><label>Akhir sesi<input v-model="filters.end_date" type="date" :max="today()" required></label><label>Halaqoh<select v-model="filters.halaqoh_id"><option value="">Semua halaqoh</option><option v-for="item in report?.halaqoh || []" :key="item.id" :value="item.id">{{ item.nama }}</option></select></label><label v-if="role !== 'ustadz'">Kategori<select v-model="filters.kategori"><option value="">Semua</option><option value="reguler">Reguler</option><option value="askar">Askar</option><option value="tahsin_luar">Tahsin luar</option></select></label><label>Status data<select v-model="filters.kelengkapan"><option value="">Semua kualitas</option><option value="complete">Lengkap</option><option value="missing">Belum diinput</option><option value="partial">Sebagian diinput</option><option value="capaian">Capaian belum lengkap</option><option value="conflict">Perlu verifikasi</option><option value="unverified">Histori belum terverifikasi</option><option value="external">Tahsin luar</option><option value="unassigned">Belum punya halaqoh</option><option value="archived">Arsip</option><option value="no_data">Tidak ada sesi</option></select></label><label>Pemantauan<select v-model="filters.risk"><option value="">Semua status</option><option value="rawan">Butuh follow-up</option><option value="pantau">Pantau</option><option value="stabil">Tanpa Alfa tercatat</option><option value="belum_data">Belum ada data</option></select></label><label class="tr-search">Cari wali, anak, atau kelompok<input v-model="filters.search" maxlength="100" placeholder="Ketik nama"></label><button :disabled="loading">{{ loading ? 'Memuat…' : 'Terapkan' }}</button><button type="button" class="tr-reset" @click="Object.assign(filters, { start_date: monthStart(), end_date: today(), halaqoh_id: '', ustadz_id: '', kategori: '', aktif: '', kelas: '', search: '', kelengkapan: '', risk: '' }); applyFilters()">Reset</button></form>
    <template v-if="report">
      <div class="tr-cards"><article><span>Wali dalam filter</span><strong>{{ report.summary.peserta.toLocaleString('id-ID') }}</strong></article><article><span>Hadir tercatat</span><strong>{{ report.summary.hadir.toLocaleString('id-ID') }}</strong><small>{{ percentage(report.summary.hadir_percent) }} dari presensi tercatat</small></article><article><span>Alfa tercatat</span><strong>{{ report.summary.alpha.toLocaleString('id-ID') }}</strong><small>Data kosong bukan Alfa</small></article><article><span>Kelengkapan input</span><strong>{{ percentage(report.summary.coverage_percent) }}</strong><small>{{ report.summary.complete_input }} / {{ report.summary.expected }} peserta-sesi</small></article><article><span>Perlu verifikasi</span><strong>{{ report.summary.conflicts.toLocaleString('id-ID') }}</strong></article><article><span>Butuh follow-up</span><strong>{{ report.summary.rawan.toLocaleString('id-ID') }}</strong><small>≥3 Alfa tercatat pada periode</small></article></div>
      <div class="tr-panel"><div class="tr-panel-heading"><div><h2>Rekap per kelompok</h2><p>Ringkasan per penempatan sesi dalam periode terpilih.</p></div><span v-if="report.summary.provisional" class="tr-pill warn">Data sementara</span></div><div class="tr-scroll"><table><thead><tr><th>Kelompok</th><th>Wali</th><th>H</th><th>S</th><th>I</th><th>A</th><th>Kehadiran</th><th>Input lengkap</th></tr></thead><tbody><tr v-if="!report.halaqoh.length"><td colspan="8" class="tr-empty">Tidak ada sesi tercatat dalam filter ini.</td></tr><tr v-for="item in report.halaqoh" :key="item.id"><td><strong>{{ item.nama }}</strong><small>{{ item.nama_ustadz || 'Guru belum ditentukan' }}</small></td><td>{{ item.total_anggota }}</td><td>{{ item.hadir }}</td><td>{{ item.sakit }}</td><td>{{ item.izin }}</td><td>{{ item.alpha }}</td><td>{{ percentage(item.hadir_percent) }}<small v-if="item.provisional">Sementara</small></td><td>{{ percentage(item.coverage_percent) }}</td></tr></tbody></table></div></div>
      <div class="tr-panel"><div class="tr-panel-heading"><div><h2>Rincian wali</h2><p>{{ total.toLocaleString('id-ID') }} wali · halaman {{ page }} dari {{ pages }}</p></div></div><div class="tr-scroll"><table><thead><tr><th>Wali / anak</th><th>Kelompok / guru</th><th>H</th><th>S</th><th>I</th><th>A</th><th>Kehadiran</th><th>Kelengkapan</th><th>Kualitas / follow-up</th><th>Terakhir hadir / capaian</th></tr></thead><tbody><tr v-if="loading && !report.rows.length"><td colspan="10" class="tr-empty">Memuat rekap…</td></tr><tr v-else-if="!report.rows.length"><td colspan="10" class="tr-empty">Tidak ada wali sesuai filter.</td></tr><template v-for="row in report.rows" :key="row.id"><tr><td><a class="tr-rapor-link" :href="raporHref(row)" target="_blank" rel="noopener"><strong>{{ row.nama_bapak }}</strong></a><small>{{ row.anak || 'Data anak belum tersedia' }}</small><small>{{ row.kategori.replaceAll('_', ' ') }} · {{ row.status_aktif ? 'Aktif' : 'Arsip' }}</small></td><td>{{ row.nama_halaqoh }}<small>{{ row.nama_ustadz }}</small></td><td>{{ row.hadir }}</td><td>{{ row.sakit }}</td><td>{{ row.izin }}</td><td>{{ row.alpha }}</td><td><strong>{{ percentage(row.hadir_percent) }}</strong><small v-if="row.provisional">Sementara</small></td><td>{{ percentage(row.coverage_percent) }}<small>{{ row.unverified ? 'Histori belum terverifikasi' : row.expected ? `${row.complete_input} / ${row.expected} peserta-sesi` : 'Kewajiban tidak diketahui' }}</small></td><td><span class="tr-pill" :class="row.quality">{{ row.quality_label }}</span><small>{{ row.risk_label }}</small></td><td>{{ row.terakhir_hadir || '—' }}<small>{{ row.materi_terakhir }}</small></td></tr><tr class="tr-detail-row"><td colspan="10"><details><summary>Detail per pekan · {{ row.details.length }} sesi</summary><div v-for="cell in row.details" :key="cell.session_date" class="tr-session"><div class="tr-session-title"><strong>Sesi Ahad {{ cell.session_date }}</strong><span class="tr-pill" :class="cell.state">{{ stateNames[cell.state] || (cell.record ? statusNames[cell.record.status] : '') || cell.state }}</span></div><p>{{ cell.owner.nama_halaqoh || 'Tanpa halaqoh' }} · {{ cell.owner.nama_ustadz || 'Guru belum ditentukan' }} · {{ cell.roster_source }}</p><p v-if="cell.missing_fields.length" class="tr-missing">Perlu dilengkapi: {{ cell.missing_fields.join(', ') }}</p><div class="tr-source" v-for="source in cell.records" :key="source.id"><span>#{{ source.id }} · {{ source.tanggal }}<small v-if="source.on_holiday">Libur; tidak dihitung</small></span><strong>{{ statusNames[source.status] || source.status }}</strong><span>{{ statusText(source) }}</span></div><p v-if="!cell.records.length" class="tr-muted">Belum ada catatan guru; status kehadiran peserta belum diketahui.</p><form v-if="(role === 'admin' || role === 'pj_tahfidz') && report.schema_ready && cell.state === 'conflict' && cell.records.length" class="tr-verify no-print" @submit.prevent="verify(row, cell)"><label>Catatan yang sah<select v-model="verifyChoice[cellKey(row, cell)]" required><option value="" disabled>Pilih setelah meninjau sumber</option><option v-for="source in cell.records" :key="source.id" :value="String(source.id)">#{{ source.id }} · {{ source.tanggal }} · {{ statusNames[source.status] }} · {{ statusText(source) }}</option><option value="0">Capaian awal saja; bukan presensi</option></select></label><label>Alasan verifikasi<input v-model="verifyNote[cellKey(row, cell)]" required maxlength="2000" placeholder="Sumber konfirmasi atau koreksi data"></label><button :disabled="saving === cellKey(row, cell)">{{ saving === cellKey(row, cell) ? 'Menyimpan…' : 'Simpan verifikasi' }}</button><small>Catatan sumber tidak dihapus. Perubahan sumber berikutnya membuat verifikasi ini stale.</small></form></div></details></td></tr></template></tbody></table></div><div class="tr-pagination no-print"><button :disabled="loading || page <= 1" @click="move(-1)">Sebelumnya</button><button :disabled="loading || page >= pages" @click="move(1)">Berikutnya</button></div></div>
    </template>
  </section>
</template>

<style scoped>
.tahsin-report-page{max-width:1400px;margin:0 auto;display:grid;gap:14px;color:#172b42}.tr-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:16px}.tr-heading h1{margin:7px 0;font-size:28px;letter-spacing:-.04em}.tr-heading p,.tr-panel-heading p{margin:0;color:#687c91;font-size:12px;line-height:1.5}.tr-kicker{font-size:10px;letter-spacing:1.2px;font-weight:850;color:#6c8095}.tr-print,.tr-filters button,.tr-pagination button,.tr-verify button{border:1px solid #d3deea;border-radius:9px;background:#fff;color:#365671;padding:9px 12px;font-weight:750;white-space:nowrap}.tr-print:disabled,.tr-filters button:disabled,.tr-pagination button:disabled,.tr-verify button:disabled{opacity:.55}.tr-error,.tr-warning,.tr-notice{margin:0;padding:12px 15px;border-radius:11px;font-size:13px}.tr-error{background:#fff0ee;color:#963a33}.tr-error button{margin-left:8px}.tr-warning{background:#fff8e7;border:1px solid #f0df9f;color:#76541c}.tr-notice{background:#e8f7ef;color:#176447}.tr-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;align-items:end;padding:15px;background:#fff;border:1px solid #e1e8f0;border-radius:14px}.tr-filters label,.tr-verify label{display:grid;gap:5px;color:#62778b;font-size:11px;font-weight:750}.tr-filters input,.tr-filters select,.tr-verify input,.tr-verify select{min-width:0;width:100%;padding:9px;border:1px solid #cfd9e4;border-radius:9px;background:#fff;color:#172b42;font:inherit}.tr-filters button{background:#245ad1;color:#fff;border-color:#245ad1}.tr-filters .tr-reset{background:#fff;color:#365671;border-color:#d3deea}.tr-cards{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.tr-cards article,.tr-panel{background:#fff;border:1px solid #e1e8f0;border-radius:14px;padding:15px}.tr-cards article{display:grid;gap:5px}.tr-cards span,.tr-cards small{color:#718399;font-size:10px}.tr-cards strong{font-size:23px;letter-spacing:-.03em}.tr-panel{min-width:0}.tr-panel-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:12px}.tr-panel-heading h2{margin:0 0 4px;font-size:16px}.tr-scroll{overflow:auto}.tr-scroll table{width:100%;border-collapse:collapse;font-size:11px}.tr-scroll th,.tr-scroll td{padding:10px 9px;text-align:left;vertical-align:top;border-bottom:1px solid #edf1f5;white-space:nowrap}.tr-scroll th{font-size:9px;color:#718399;text-transform:uppercase}.tr-scroll td strong{font-size:11px}.tr-scroll td small{display:block;margin-top:4px;color:#77899a;white-space:normal;max-width:220px;line-height:1.4}.tr-empty{text-align:center!important;padding:28px!important;color:#718399}.tr-pill{display:inline-flex;border-radius:20px;padding:4px 7px;background:#eef3f7;color:#52687e;font-size:9px;font-weight:800;white-space:nowrap}.tr-pill.warn,.tr-pill.conflict,.tr-pill.invalid_date{background:#fff1db;color:#916314}.tr-pill.missing,.tr-pill.capaian,.tr-pill.presensi_incomplete{background:#fff0ee;color:#963a33}.tr-pill.complete{background:#e8f7ef;color:#176447}.tr-pill.unverified{background:#edf2fb;color:#3e5e9b}.tr-detail-row>td{padding:0!important;white-space:normal!important}.tr-detail-row details{padding:9px 12px}.tr-detail-row summary{cursor:pointer;color:#245ad1;font-weight:750}.tr-session{display:grid;gap:7px;padding:12px 0;border-bottom:1px solid #e6edf4}.tr-session-title{display:flex;justify-content:space-between;align-items:center;gap:10px}.tr-session p{margin:0;color:#708196;font-size:10px;line-height:1.5}.tr-missing{color:#a14236!important}.tr-source{display:grid;grid-template-columns:170px 80px minmax(200px,1fr);gap:10px;padding:8px;border-radius:8px;background:#f7f9fb;font-size:10px}.tr-source small{display:block;color:#a14236}.tr-muted{color:#7d8a98;font-size:10px}.tr-verify{display:grid;grid-template-columns:1fr 1fr auto;gap:9px;align-items:end;padding:12px;background:#fff8e7;border:1px solid #f0df9f;border-radius:10px}.tr-verify button{background:#1b7848;color:#fff;border:0}.tr-verify small{grid-column:1/-1;color:#786432;font-size:10px}.tr-pagination{display:flex;justify-content:space-between;padding-top:12px}.tr-pagination button:first-child{margin-right:auto}@media(max-width:900px){.tr-cards{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:620px){.tr-heading{align-items:flex-start;flex-direction:column}.tr-print{width:100%}.tr-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.tr-verify{grid-template-columns:1fr}.tr-source{grid-template-columns:1fr;gap:4px}.tr-scroll table{min-width:860px}}@media print{.no-print{display:none!important}.tahsin-report-page{max-width:none}.tr-panel{break-inside:avoid}.tr-detail-row details{display:block}.tr-detail-row details>summary{display:none}.tr-session{break-inside:avoid}}
.tr-export-actions{display:flex;gap:8px;align-items:center}.tr-export-actions a{text-decoration:none}.tr-export-actions .disabled{opacity:.55;pointer-events:none}@media(max-width:620px){.tr-export-actions{width:100%}.tr-export-actions>*{flex:1;text-align:center}}
.tr-rapor-link{color:#245ad1;text-decoration:none}.tr-rapor-link:hover{text-decoration:underline}</style>
